draw:
var V = 6.0, Rg = p.rg;
var R1 = p.r1, R2 = p.r2, R3 = p.r3, R4 = p.r4;

// node equations for VA, VB with P at 6 V and Q at 0 V
var a11 = 1/R1 + 1/R2 + 1/Rg, a12 = -1/Rg, b1 = V/R1;
var a22 = 1/R3 + 1/R4 + 1/Rg, a21 = -1/Rg, b2 = V/R3;
var det = a11*a22 - a12*a21;
var VA = (b1*a22 - a12*b2) / det;
var VB = (a11*b2 - b1*a21) / det;
var Ig = (VA - VB) / Rg;
var Itot = (V - VA)/R1 + (V - VB)/R3;
var Rpq = V / Itot;

var cx = W/2, cy = H/2;
var rx = Math.min(W*0.34, 190), ry = Math.min(H*0.30, 78);
var P = [cx - rx, cy], Q = [cx + rx, cy];
var A = [cx, cy - ry], B = [cx, cy + ry];

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
ctx.textAlign = "center";
ctx.textBaseline = "middle";

function wire(u, v, col) {
  ctx.strokeStyle = col;
  ctx.beginPath(); ctx.moveTo(u[0], u[1]); ctx.lineTo(v[0], v[1]); ctx.stroke();
}
function box(u, v, label, col) {
  var mx = (u[0]+v[0])/2, my = (u[1]+v[1])/2;
  var dx = v[0]-u[0], dy = v[1]-u[1];
  var L = Math.sqrt(dx*dx + dy*dy); dx /= L; dy /= L;
  var w = 20, h = 9;
  ctx.save();
  ctx.translate(mx, my);
  ctx.rotate(Math.atan2(dy, dx));
  ctx.fillStyle = C.paper;
  ctx.fillRect(-w, -h, 2*w, 2*h);
  ctx.strokeStyle = col;
  ctx.strokeRect(-w, -h, 2*w, 2*h);
  ctx.restore();
  ctx.fillStyle = C.ink;
  ctx.fillText(label, mx - dy*22, my + dx*22);
}
function node(u, name, volts) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(u[0], u[1], 4, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText(name + "  " + volts, u[0], u[1] - 16);
}

wire(P, A, C.rule); wire(A, Q, C.rule);
wire(P, B, C.rule); wire(B, Q, C.rule);
wire(A, B, C.figure);

box(P, A, R1.toFixed(0) + " Ω", C.rule);
box(A, Q, R2.toFixed(0) + " Ω", C.rule);
box(P, B, R3.toFixed(0) + " Ω", C.rule);
box(B, Q, R4.toFixed(0) + " Ω", C.rule);
box(A, B, Rg.toFixed(0) + " Ω", C.figure);

ctx.fillStyle = C.ink;
ctx.fillText("P  6.00 V", P[0] - 4, P[1] - 16);
ctx.fillText("Q  0.00 V", Q[0] + 4, Q[1] - 16);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(P[0], P[1], 4, 0, Math.PI*2); ctx.fill();
ctx.beginPath(); ctx.arc(Q[0], Q[1], 4, 0, Math.PI*2); ctx.fill();
node(A, "A", VA.toFixed(3) + " V");
ctx.fillStyle = C.ink;
ctx.fillText("B  " + VB.toFixed(3) + " V", B[0], B[1] + 18);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(B[0], B[1], 4, 0, Math.PI*2); ctx.fill();

// animated charge in the bridge arm, speed set by the galvanometer current
var speed = Math.min(1.2, Math.abs(Ig) * 260);
var dir = Ig >= 0 ? 1 : -1;
if (speed > 0.004) {
  for (var k = 0; k < 4; k++) {
    var f = ((t * speed + k/4) % 1);
    var yy = A[1] + dir * f * (B[1] - A[1]);
    if (dir < 0) yy = B[1] + f * (A[1] - B[1]);
    ctx.fillStyle = C.figure;
    ctx.beginPath(); ctx.arc(A[0], yy, 3, 0, Math.PI*2); ctx.fill();
  }
} else {
  ctx.fillStyle = C.figure;
  ctx.fillText("balanced: no current", A[0] + 96, cy);
}

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("ratio PA/AQ = " + (R1/R2).toFixed(3), 8, H - 26);
ctx.fillText("ratio PB/BQ = " + (R3/R4).toFixed(3), 8, H - 10);

out.note = "V(A) - V(B) = " + (VA - VB).toFixed(4) + " V, bridge current = "
  + (Ig*1000).toFixed(3) + " mA, R(P to Q) = " + Rpq.toFixed(2) + " Ω";
